seen = []
def ok(req):
    seen.append(req)
    if "missing" in str(req.url):
        return httpx2.Response(404, headers={"X-Error-Code": "RepoNotFound"}, json={"error": "nope"})
    return httpx2.Response(200, json={"id": "a/b", "sha": "deadbeef", "siblings": []})
configure_hub_http(httpx2.MockTransport(ok))
print(current_revision("a/b"))
r = seen[-1]; print(r.url, r.headers["X-Acme-Job"], r.headers["user-agent"], r.extensions["timeout"])
try: current_revision("a/missing")
except Exception as e: print("raised", type(e).__name__)
def boom(req): raise httpx2.ConnectError("down", request=req)
configure_hub_http(httpx2.MockTransport(boom))
print(current_revision("a/b"))
def slow(req): raise httpx2.ReadTimeout("slow", request=req)
configure_hub_http(httpx2.MockTransport(slow))
print(current_revision("a/b"))
EOF
python _check.py; rm _check.py; pytest -q

